from __future__ import annotations

import hashlib
from pathlib import Path

PAPER = Path(__file__).resolve().parents[1]
REPO = PAPER.parents[1]
MG = PAPER / "machine-generated"

def sha256_of(path) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def header(generator: str, sources: list[tuple[str, str]], command: str) -> str:
    src = ", ".join(f"{path} (sha256 {sha})" for path, sha in sources)
    return (f"% MACHINE-GENERATED by {generator} from {src}.\n"
            "% DO NOT EDIT: the next run overwrites it.\n"
            f"% Regenerate with: {command}\n")
